def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='La llamada generación del 27 reúne a un grupo de poetas que dieron a la lírica española una de sus épocas más brillantes. Este capítulo la describe a partir de la figura central de Federico García Lorca, con tres facetas: el poeta neopopular del Romancero gitano, el poeta del dolor de Poeta en Nueva York y del Llanto por Ignacio Sánchez Mejías, y el dramaturgo de Bodas de sangre y La casa de Bernarda Alba. El lector aprenderá a comentar un romance, una elegía y una escena teatral lorquiana.',
        quotes=[Q('es_g27', 'Se denomina generación del 27 a unos escritores y poetas españoles del siglo xx que se dio a conocer en el panorama cultural alrededor de 1927'), Q('en_g27', 'The Generation of \'27 (Spanish: Generación del 27) was an influential group of poets that arose in Spanish literary circles between 1923 and 1927')]))
    P.append(dict(text='Góngora en el Ateneo de Sevilla\nSe denomina generación del 27 a escritores y poetas que se dieron a conocer hacia 1927, con motivo del homenaje a Luis de Góngora que se celebró en el Ateneo de Sevilla para conmemorar el tercer centenario de la muerte del poeta barroco. La fuente inglesa fecha su aparición entre 1923 y 1927, y su primera reunión formal en Sevilla en 1927. Los poetas reivindicaron la segunda época de Góngora, la culterana, rechazada por la crítica oficial. Fueron el relevo de la generación del 98 y del novecentismo. Entre ellos figuran Pedro Salinas, Jorge Guillén, Dámaso Alonso, Gerardo Diego, Federico García Lorca, Vicente Aleixandre, Rafael Alberti, Luis Cernuda, Emilio Prados y Manuel Altolaguirre.',
        quotes=[Q('es_g27', 'con motivo del homenaje a Luis de Góngora organizado aquel año por José María Romero Martínez en el Ateneo de Sevilla'), Q('en_g27', 'Their first formal meeting took place in Seville in 1927 to mark the 300th anniversary of the death of the baroque poet Luis de Góngora.'), Q('es_g27', 'el acto de reivindicación en el Ateneo de Sevilla de la segunda época de Luis de Góngora, la llamada culterana'), Q('es_damaso', 'donde se doctora en 1928 con un estudio sobre la evolución de la sintaxis de Luis de Góngora')]))
    P.append(dict(text='¿Una generación?\nLa crítica discute que sea realmente una generación. Pedro Salinas puso en duda el concepto porque el grupo no cumple los criterios historiográficos: nacimiento en años cercanos (la mayoría en un lapso de diecisiete años), formación intelectual semejante, relaciones personales, actos colectivos, un acontecimiento generacional, un guía, un lenguaje común y el anquilosamiento de la generación anterior. En realidad coinciden en una sólida formación universitaria y en considerar a Juan Ramón Jiménez como poeta de referencia, y se conocieron en la Residencia de Estudiantes. Por eso se habla más bien de un grupo generacional o «constelación», una generación «cumulativa» que asume los logros de las anteriores, y de la llamada Edad de Plata. Otras propuestas fueron «generación Guillén-Lorca» o «generación de la amistad».',
        quotes=[Q('es_g27', 'El concepto y la denominación de grupo generacional fue ya puesto en duda por uno de sus miembros, Pedro Salinas'), Q('es_g27', 'Coinciden los elegidos en una sólida formación universitaria y en la consideración de Juan Ramón Jiménez como poeta de referencia.'), Q('es_g27', 'constituyen una generación «cumulativa» que asume los logros de las anteriores'), Q('en_g27', 'The Generation of \'27 has also been called, with lesser success, "Generation of the Dictatorship"')]))
    P.append(dict(text='Tradición y vanguardia\nLa generación del 27 no renunció a la tradición: todos ejercieron estéticas de vanguardia, pero no renunciaron a la tradición literaria culta del Siglo de Oro ni a la popular, y evolucionaron desde el neopopularismo hasta el surrealismo. Los neopopularistas, Alberti y Lorca, buscan en el Romancero y en la lírica cancioneril fuentes populares. En la Residencia de Estudiantes entraron en contacto con las vanguardias artísticas y científicas, y en el Centro de Estudios Históricos asimilaron las tradiciones culturales hispánicas. La fuente inglesa resume la evolución: de la poesía pura, con énfasis en la música, a futurismo, cubismo, ultraísmo y creacionismo, hasta el surrealismo, para dispersarse en el exilio tras la Guerra Civil.',
        quotes=[Q('es_g27', 'no renunciaron a la tradición literaria culta del Siglo de Oro o la popular, y evolucionando desde el neopopularismo al surrealismo'), Q('es_g27', 'Los poetas del neopopularismo o neopopularistas: Rafael Alberti y Federico García Lorca'), Q('es_g27', 'la Residencia de Estudiantes, donde entraron en contacto con las vanguardias artísticas y científicas'), Q('en_g27', 'It evolved from pure poetry, which emphasized music in poetry, in the vein of Baudelaire')]))
    P.append(dict(text='Los poetas del grupo\nLa generación reúne voces muy distintas. Jorge Guillén (Valladolid, 1893-Málaga, 1984), poeta de Cántico, es por su inclinación a la poesía pura el discípulo más directo de Juan Ramón Jiménez. Pedro Salinas (Madrid, 1891-Boston, 1951) escribió la trilogía amorosa La voz a ti debida, Razón de amor y Largo lamento. Dámaso Alonso (Madrid, 1898-1990) fue poeta y filólogo, director de la Real Academia Española, autor de Hijos de la ira. Rafael Alberti (El Puerto de Santa María, 1902-1999) obtuvo en 1924 el Premio Nacional de Poesía por Marinero en tierra. Luis Cernuda (Sevilla, 1902-México, 1963) reunió su obra en La realidad y el deseo. Vicente Aleixandre (Sevilla, 1898-Madrid, 1984) recibió el Premio Nobel en 1977.',
        quotes=[Q('es_guillen', 'Por su inclinación a la poesía pura, algunos críticos lo consideran el discípulo más directo de Juan Ramón Jiménez.'), Q('es_salinas', 'Ella fue la destinataria de su trilogía poética La voz a ti debida, Razón de amor y Largo lamento.'), Q('es_damaso', 'fue un escritor y filólogo español, director de la Real Academia Española'), Q('es_alberti', 'En 1924, Rafael Alberti recibió el Premio Nacional de Poesía por Marinero en tierra'), Q('es_cernuda', 'se integraron en Égloga, elegía, oda dentro de su libro La realidad y el deseo de 1936'), Q('es_aleixandre', 'así como el Premio Nobel de Literatura en 1977')]))
    P.append(dict(text='Federico García Lorca\nFederico García Lorca (Fuente Vaqueros, Granada, 1898-camino de Víznar a Alfacar, 1936) fue poeta, prosista, dramaturgo y director teatral, y alcanzó reconocimiento internacional como miembro emblemático de la generación del 27. Su poesía incorporó motivos tradicionales andaluces y estilos vanguardistas. Alcanzó la fama con el Romancero gitano (1928); tras su estancia en Nueva York entre 1929 y 1930, escribió sus obras teatrales más conocidas: Bodas de sangre (1932), Yerma (1934) y La casa de Bernarda Alba (1936). Fue asesinado por el bando sublevado un mes después del golpe de Estado de 1936; sus restos nunca se han encontrado. La fuente inglesa lo describe como un miembro emblemático del grupo, que introdujo los postulados del simbolismo, el futurismo y el surrealismo.',
        quotes=[Q('es_lorca', 'fue un poeta, prosista, dramaturgo y director teatral español'), Q('es_lorca', 'Su poesía incorporó motivos tradicionales andaluces y estilos vanguardistas.'), Q('es_lorca', 'Después de una estancia en la ciudad de Nueva York entre 1929 y 1930'), Q('es_lorca', 'Sus restos nunca se han encontrado.'), Q('en_lorca', 'García Lorca achieved international recognition as an emblematic member of the Generation of \'27')]))
    P.append(dict(text='El Romancero gitano\nEl Romancero gitano (1928) está compuesto por dieciocho romances con símbolos como la noche, la muerte, el cielo y la luna. Todos tratan la cultura gitana, aunque el hilo conductor es la pena. Lorca nunca pensó en el libro como un documento histórico sobre la etnia gitana: el espacio es una Andalucía estilizada, alejada del costumbrismo y del tipismo folclórico, que presenta una síntesis entre poesía popular y alta poesía. Refleja las penas de un pueblo marginado y perseguido por la autoridad, y el propio Lorca dijo que su interés estaba en el choque entre fuerzas encontradas. Los recursos más frecuentes son la metáfora, la personificación, la comparación, la repetición y la sinestesia.',
        quotes=[Q('es_romancero', 'Está compuesta por dieciocho romances con símbolos como la noche, la muerte, el cielo, la luna.'), Q('es_romancero', 'el hilo conductor a lo largo de todo el poemario es la pena'), Q('es_romancero', 'Federico García Lorca estiliza el mundo gitano, alejado del costumbrismo y tipismo folclórico.'), Q('es_romancero', 'Presenta una síntesis entre poesía popular y alta poesía.'), Q('en_gypsy', 'it is composed of eighteen romances with subjects like the night, death, the sky, and the moon')]))
    P.append(dict(text='Romance de la luna, luna\nEl «Romance de la luna, luna» es uno de los más conocidos del libro. Cuenta cómo la luna baja a la fragua, con su «polisón de nardos», ante un niño que la mira; ella baila y enseña sus senos «de duro estaño». El niño advierte: «Huye luna, luna, luna. / Si vinieran los gitanos, / harían con tu corazón / collares y anillos blancos». Cuando llegan los gitanos, el niño está sobre el yunque «con los ojillos cerrados» y «por el cielo va la luna / con un niño de la mano»: el niño ha muerto. La luna, símbolo de la muerte en Lorca, seduce al niño; la imagen es metafórica y mítica. La forma es el romance octosilábico con rima asonante en los versos pares, la métrica tradicional del romancero, renovada con imágenes de vanguardia.',
        quotes=[Q('ws_luna', 'LA luna vino a la fragua', 'con su polisón de nardos.'), Q('ws_luna', 'Huye luna, luna, luna.', 'harían con tu corazón'), Q('ws_luna', 'Por el cielo va la luna', 'con un niño de la mano.'), Q('es_lorca', 'Su poesía incorporó motivos tradicionales andaluces y estilos vanguardistas.')]))
    P.append(dict(text='Romance sonámbulo y La casada infiel\nEl «Romance sonámbulo» comienza con un verso que se repite como estribillo: «Verde que te quiero verde. / Verde viento. Verdes ramas. / El barco sobre la mar / y el caballo en la montaña». Una muchacha sueña en su baranda, «verde carne, pelo verde, con los ojos de fría plata», bajo la luna gitana, y las cosas la miran sin que ella pueda mirarlas. El color verde es símbolo ambiguo de deseo y muerte. En «La casada infiel», el yo poético cuenta cómo se llevó a una mujer al río creyendo que era soltera, y descubre que «tenía marido»; el poema tiene el tono de una confidencia desenfadada, con la imagen erótica de los pechos «como ramos de jacintos». Las dos obras muestran la mezcla lorquiana de lo popular y lo vanguardista.',
        quotes=[Q('ws_sonambulo', 'VERDE que te quiero verde.', 'y el caballo en la montaña.'), Q('ws_sonambulo', 'Con la sombra en la cintura,', 'con los ojos de fría plata.'), Q('ws_casada', 'Y que yo me la llevé al río', 'pero tenía marido.'), Q('ws_casada', 'y se me abrieron de pronto', 'como ramos de jacintos.'), Q('es_romancero', 'Transcurre entre dos motivos centrales, Andalucía y los gitanos, tratados de manera metafórica y mítica.')]))
    P.append(dict(text='La canción del jinete\nLa «Canción del jinete» es una canción breve con tono de presagio: «Córdoba. / Lejana y sola. / Jaca negra, luna grande, / y aceitunas en mi alforja. / Aunque sepa los caminos / yo nunca llegaré a Córdoba». El jinete avanza hacia una ciudad que nunca alcanzará, y la muerte lo mira desde las torres. El paisaje es breve: Córdoba, jaca, luna, aceitunas. Los versos de arte menor y el estribillo «lejana y sola» dan una musicalidad que recuerda al cantar popular, y el simbolismo de la luna roja y la jaca negra anuncia la muerte. Aunque pertenece a Canciones y no al Romancero, es un buen ejemplo de la síntesis de poesía popular y alta poesía.',
        quotes=[Q('ws_jinete', 'Córdoba.', 'Lejana y sola.'), Q('ws_jinete', 'Aunque sepa los caminos', 'yo nunca llegaré a Córdoba.'), Q('ws_jinete', 'La muerte me está mirando', 'desde las torres de Córdoba.'), Q('es_romancero', 'Presenta una síntesis entre poesía popular y alta poesía.')]))
    P.append(dict(text='Poeta en Nueva York\nPoeta en Nueva York es un poemario escrito entre 1929 y 1930, durante la estancia de Lorca en la Universidad de Columbia y en su viaje a Cuba, y publicado por primera vez en 1940, cuatro años después de su asesinato. Lorca salió de España en 1929, tras un fracaso sentimental y un profundo dilema interior, y vivió en Nueva York del 25 de junio de 1929 al 4 de marzo de 1930. La sociedad norteamericana le causó una profunda aversión hacia el capitalismo y la industrialización, y repudió el trato dado a la minoría negra. El libro es un «grito de horror, de denuncia contra la injusticia y la discriminación, contra la deshumanización». La fuente inglesa lo considera una de las obras más importantes de Lorca.',
        quotes=[Q('es_poeta_ny', 'Poeta en Nueva York es el título de un poemario escrito por Federico García Lorca entre 1929 y 1930'), Q('es_poeta_ny', 'Vivió en Nueva York del 25 de junio de 1929 al 4 de marzo de 1930'), Q('es_poeta_ny', 'una profunda aversión hacia el capitalismo y la industrialización de la sociedad moderna'), Q('en_poeta_ny', 'Poet in New York (in Spanish, Poeta en Nueva York) is one of the most important works of the Spanish author Federico García Lorca.')]))
    P.append(dict(text='Llanto por Ignacio Sánchez Mejías\nEl Llanto por Ignacio Sánchez Mejías es la elegía que Lorca dedicó a la muerte del torero y amigo, en cuatro partes. La primera, «La cogida y la muerte», se construye alrededor de un estribillo: «A las cinco de la tarde». Empieza: «Eran las cinco en punto de la tarde. / Un niño trajo la blanca sábana / a las cinco de la tarde», y cada verso describe un hecho de la muerte seguido del mismo estribillo, de modo que la hora se vuelve obsesión. Hay imágenes de vanguardia: «las campanas de arsénico», «la muerte puso huevos en la herida». La repetición convierte la elegía en un conjuro y en una campana: es la forma tradicional del planto, renovada con metáfora surrealista.',
        quotes=[Q('ws_llanto', '1. La cogida y la muerte', 'Eran las cinco en punto de la tarde.'), Q('ws_llanto', 'Un niño trajo la blanca sábana', 'a las cinco de la tarde.'), Q('ws_llanto', 'la muerte puso huevos en la herida', 'a las cinco de la tarde.'), Q('ws_llanto', 'Las campanas de arsénico y el humo', 'a las cinco de la tarde.'), Q('es_lorca', 'Llanto por la muerte de Ignacio Sánchez Mejías (1935) es una elegía de incontenible dolor y emoción que actúa de homenaje al torero sevillano'), Q('es_g27', 'Llanto por Ignacio Sánchez Mejías, planto compuesto a la muerte de un torero amigo suyo.')]))
    P.append(dict(text='Bodas de sangre\nBodas de sangre es una tragedia en verso y en prosa escrita en 1931 y estrenada el 8 de marzo de 1933 en el Teatro Beatriz de Madrid. Su tema principal es la vida y la muerte, de manera arcana y ancestral, con mitos, leyendas y paisajes que conducen a los celos, la persecución y la muerte; el amor es la única fuerza que puede vencerla. Los objetos simbólicos (el puñal, el cuchillo, la navaja) y los elementos naturales como la luna anuncian la tragedia. Se basa en un suceso real ocurrido en Níjar (Almería) el 22 de julio de 1928, que Lorca conoció por la prensa; Carmen de Burgos ya lo había tratado en una novela corta. La fuente inglesa la fecha en 1932 y la sitúa como la primera de la trilogía rural.',
        quotes=[Q('es_bodas', 'Bodas de sangre es una tragedia en verso y en prosa del escritor español Federico García Lorca, escrita en el año 1931.'), Q('es_bodas', 'El tema principal tratado en este gran drama es la vida y la muerte.'), Q('es_bodas', 'Es constante en la obra lorquiana la obsesión por el puñal, el cuchillo y la navaja'), Q('es_bodas', 'se produjeron el 22 de julio de 1928 en el Cortijo del Fraile'), Q('en_bodas', 'It was written in 1932 and first performed at Teatro Beatriz in Madrid in March 1933')]))
    P.append(dict(text='La casa de Bernarda Alba\nLa casa de Bernarda Alba, obra en tres actos de 1936, fue la última de Lorca: la terminó el 19 de junio, dos meses antes de su asesinato; solo pudo estrenarse y publicarse en 1945, en Buenos Aires, gracias a Margarita Xirgu. Expone la historia de Bernarda, que, viuda por segunda vez a los 60 años, impone a sus hijas ocho años del más riguroso luto. Lorca describe la España profunda de principios del siglo XX, con una sociedad tradicional muy violenta en la que la mujer desempeña un papel secundario, y con fanatismo religioso. Se inspiró en personas de la familia Alba del pueblo granadino de Valderrubio. La obra es drama de la opresión y de la represión del deseo.',
        quotes=[Q('es_bernarda', 'La casa de Bernarda Alba es una obra teatral en tres actos escrita en 1936 por Federico García Lorca.'), Q('es_bernarda', 'Sólo pudo estrenarse y publicarse en 1945, en Buenos Aires, gracias a la iniciativa de la actriz Margarita Xirgu.'), Q('es_bernarda', 'tras haber enviudado por segunda vez a los 60 años, decide vivir los siguientes ocho años en el más riguroso luto'), Q('en_bernarda', 'The House of Bernarda Alba was García Lorca\'s last play, completed on 19 June 1936')]))
    P.append(dict(text='El final de Bernarda Alba\nEn el último acto, la hija menor, Adela, se suicida creyendo que han matado a Pepe el Romano. Bernarda, sin lágrimas, dice: «¡Mi hija ha muerto virgen! Llevadla a su cuarto y vestirla como si fuera doncella. ¡Nadie dirá nada!». Después ordena silencio: «Y no quiero llantos. La muerte hay que mirarla cara a cara. ¡Silencio!» y concluye: «¡Nos hundiremos todas en un mar de luto!». El discurso resume el tema de la obra: la apariencia pesa más que la verdad y la autoridad impone el silencio. Las acotaciones («en voz baja, como un rugido») muestran la dureza del personaje. La tragedia se cierra con la palabra «Silencio», que simboliza la opresión.',
        quotes=[Q('ws_bernarda3', '¡Mi hija ha muerto virgen!'), Q('ws_bernarda3', 'La muerte hay que mirarla cara a cara.'), Q('ws_bernarda3', '¡Nos hundiremos todas en un mar de luto!'), Q('ws_bernarda3', '(En voz baja, como un rugido.)'), Q('es_bernarda', 'Lorca describe la España profunda de principios del siglo XX')]))
    P.append(dict(role='definition', text='Neopopularismo: tendencia de Lorca y Alberti que busca en el Romancero, la lírica cancioneril y el folclore fuentes populares, que se renuevan con imágenes de vanguardia. Romance: composición en versos octosílabos con rima asonante en los pares, forma típica del Romancero que Lorca recupera en el Romancero gitano.',
        quotes=[Q('es_g27', 'Los poetas del neopopularismo o neopopularistas: Rafael Alberti y Federico García Lorca'), Q('es_romancero', 'Presenta una síntesis entre poesía popular y alta poesía.')]))
    P.append(dict(role='consejo', text='Para comentar un poema de Lorca, busque primero los símbolos (luna, caballo, verde, cuchillo, agua) y pregúntese a qué fuerza remiten: casi siempre a la muerte, al deseo o al destino. Después describa la forma tradicional (romance, copla, estribillo) y cómo la renueva una imagen de vanguardia.',
        quotes=[Q('es_romancero', 'Está compuesta por dieciocho romances con símbolos como la noche, la muerte, el cielo, la luna.'), Q('es_bodas', 'Es constante en la obra lorquiana la obsesión por el puñal, el cuchillo y la navaja')]))
    P.append(dict(role='self_check', text='¿Por qué se llama generación del 27? ¿Qué es el neopopularismo? ¿Qué simboliza la luna en el Romance de la luna, luna? ¿Qué función tiene el estribillo del Llanto? ¿Qué defiende y qué reprime Bernarda?',
        quotes=[Q('es_g27', 'con motivo del homenaje a Luis de Góngora organizado aquel año por José María Romero Martínez en el Ateneo de Sevilla'), Q('en_bernarda', 'The House of Bernarda Alba was García Lorca\'s last play, completed on 19 June 1936')]))
    return P


def extend(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(text='Granada, Madrid y la Residencia\nLorca nació en Fuente Vaqueros en 1898, hijo de un hacendado y de una maestra de escuela que fomentó su gusto literario. En la primavera de 1919, con la ayuda de Fernando de los Ríos, que convenció a sus padres, se trasladó a Madrid para continuar sus estudios en la Residencia de Estudiantes, donde se unió a amigos de la tertulia granadina de El Rinconcillo. La Residencia fue el centro de contacto con las vanguardias y de amistades decisivas, entre ellas la de Salvador Dalí y Luis Buñuel. La fuente inglesa la describe como una residencia progresista, inspirada en Oxford y Cambridge. Allí empezó a formarse el grupo que, años más tarde, se daría a conocer en Sevilla.',
        quotes=[Q('es_lorca', 'En la primavera de 1919, varios de sus amigos de la tertulia El Rinconcillo se trasladaron a Madrid'), Q('es_lorca', 'Su padre fue el hacendado Federico García Rodríguez'), Q('en_lorca', 'Fernando de los Rios persuaded García Lorca\'s parents to let him move to the progressive, Oxbridge-inspired Residencia de Estudiantes in Madrid in 1919'), Q('es_lorca', 'Además, durante un tiempo mantuvo una estrecha relación con Salvador Dalí.')]))
    P.append(dict(text='La Barraca y el teatro\nEn 1931 Lorca fue nombrado director de La Barraca, un grupo de teatro universitario que codirigió con Eduardo Ugarte y que representó obras del Siglo de Oro (Calderón, Lope de Vega, Cervantes) por ciudades y pueblos de España. Es un dato clave para entender su teatro: Lorca quería llevar el teatro clásico a un público que no podía acudir a los teatros de las capitales. Más tarde, en Buenos Aires, dirigió Bodas de sangre, que se representó más de ciento cincuenta veces, y adaptó La dama boba de Lope de Vega. Esa doble condición de autor y director explica la importancia de la imagen, la música y el gesto en sus obras.',
        quotes=[Q('es_lorca', 'Junto a Eduardo Ugarte, el escritor granadino codirigió La Barraca, un grupo de teatro universitario'), Q('en_lorca', 'In 1931, García Lorca was appointed director of a student theatre company, Teatro Universitario La Barraca (The Shack).'), Q('es_lorca', 'tuvo la oportunidad de dirigir Bodas de sangre, que fue representada más de ciento cincuenta veces'), Q('es_lorca', 'una adaptación de La dama boba de Lope de Vega')]))
    P.append(dict(text='El asesinato de Lorca\nLorca fue asesinado por el bando sublevado un mes después del golpe de Estado de 1936, en el camino de Víznar a Alfacar (Granada), el 18 de agosto de 1936, y sus restos nunca se han encontrado. La fuente en español señala que su homosexualidad jugó un papel importante en el asesinato. La fuente inglesa lo describe como asesinado por fuerzas nacionalistas al comienzo de la Guerra Civil y recuerda que informes policiales publicados en 2015 concluyen que fue ejecutado por fuerzas fascistas. Tras la guerra, el nombre de Lorca fue prohibido en España; su obra se difundió por el exilio, y La casa de Bernarda Alba se estrenó en Buenos Aires en 1945. La generación del 27 se dispersó en el exilio interior y exterior.',
        quotes=[Q('es_lorca', 'en su asesinato por el bando sublevado un mes después del golpe de Estado'), Q('es_lorca', 'camino de Víznar a Alfacar, Granada, 18 de agosto de 1936'), Q('en_lorca', 'García Lorca was assassinated by Nationalist forces at the beginning of the Spanish Civil War.'), Q('en_lorca', 'Police reports released by radio station Cadena SER in April 2015, conclude that Lorca was executed by fascist forces.')]))
    return P


